CREATE TABLE public.friendships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(requester_id <> recipient_id));
GRANT SELECT, INSERT, DELETE ON public.friendships TO authenticated; GRANT ALL ON public.friendships TO service_role;
ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX friendships_pair ON public.friendships (least(requester_id,recipient_id),greatest(requester_id,recipient_id));
CREATE POLICY friendship_read ON public.friendships FOR SELECT TO authenticated USING(auth.uid() IN (requester_id,recipient_id));
CREATE POLICY friendship_request ON public.friendships FOR INSERT TO authenticated WITH CHECK(requester_id=auth.uid() AND status='pending');
CREATE POLICY friendship_delete ON public.friendships FOR DELETE TO authenticated USING(auth.uid() IN (requester_id,recipient_id));
CREATE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND ((requester_id=a AND recipient_id=b) OR (requester_id=b AND recipient_id=a))); $$;
REVOKE ALL ON FUNCTION public.are_friends(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.are_friends(uuid,uuid) TO authenticated;
CREATE FUNCTION public.accept_friend(request_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.friendships SET status='accepted' WHERE id=request_id AND recipient_id=auth.uid() AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.accept_friend(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.accept_friend(uuid) TO authenticated;
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL DEFAULT '' CHECK(length(body)<=2000), storage_path text, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, CHECK(sender_id <> recipient_id), CHECK(length(trim(body))>0 OR storage_path IS NOT NULL));
GRANT SELECT, INSERT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX messages_pair_time ON public.messages(sender_id,recipient_id,created_at DESC);
CREATE POLICY message_read ON public.messages FOR SELECT TO authenticated USING(auth.uid() IN (sender_id,recipient_id));
CREATE POLICY message_send ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.are_friends(sender_id,recipient_id) AND read_at IS NULL AND (storage_path IS NULL OR (storage_path LIKE auth.uid()::text || '/%' AND EXISTS(SELECT 1 FROM public.media WHERE owner_id=auth.uid() AND media.storage_path=messages.storage_path))));
CREATE FUNCTION public.mark_messages_read(friend_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.messages SET read_at=now() WHERE recipient_id=auth.uid() AND sender_id=friend_id AND read_at IS NULL; $$;
REVOKE ALL ON FUNCTION public.mark_messages_read(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.mark_messages_read(uuid) TO authenticated;
CREATE TABLE public.stories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, storage_path text NOT NULL, caption text NOT NULL DEFAULT '' CHECK(length(caption)<=160), audience text NOT NULL DEFAULT 'friends' CHECK(audience IN ('friends','selected')), selected_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours');
GRANT SELECT, INSERT, DELETE ON public.stories TO authenticated; GRANT ALL ON public.stories TO service_role;
ALTER TABLE public.stories ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_view_story(story_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.stories s WHERE s.id=story_id AND s.expires_at>now() AND (s.owner_id=auth.uid() OR (public.are_friends(s.owner_id,auth.uid()) AND (s.audience='friends' OR auth.uid()=ANY(s.selected_ids))))); $$;
REVOKE ALL ON FUNCTION public.can_view_story(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_view_story(uuid) TO authenticated;
CREATE POLICY story_read ON public.stories FOR SELECT TO authenticated USING(owner_id=auth.uid() OR public.can_view_story(id));
CREATE POLICY story_insert ON public.stories FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.media m WHERE m.owner_id=auth.uid() AND m.storage_path=stories.storage_path));
CREATE POLICY story_delete ON public.stories FOR DELETE TO authenticated USING(owner_id=auth.uid());
CREATE FUNCTION public.normalize_story() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.created_at=now(); NEW.expires_at=NEW.created_at+interval '24 hours'; IF NEW.audience='selected' AND cardinality(NEW.selected_ids)=0 THEN RAISE EXCEPTION 'Choose at least one friend'; END IF; IF EXISTS(SELECT 1 FROM unnest(NEW.selected_ids) u WHERE NOT public.are_friends(NEW.owner_id,u)) THEN RAISE EXCEPTION 'Audience must contain friends only'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER normalize_story BEFORE INSERT ON public.stories FOR EACH ROW EXECUTE FUNCTION public.normalize_story();
CREATE TABLE public.story_views(story_id uuid NOT NULL REFERENCES public.stories(id) ON DELETE CASCADE, viewer_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, viewed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(story_id,viewer_id));
GRANT SELECT, INSERT ON public.story_views TO authenticated; GRANT ALL ON public.story_views TO service_role;
ALTER TABLE public.story_views ENABLE ROW LEVEL SECURITY;
CREATE POLICY views_read ON public.story_views FOR SELECT TO authenticated USING(viewer_id=auth.uid() OR EXISTS(SELECT 1 FROM public.stories WHERE id=story_id AND owner_id=auth.uid()));
CREATE POLICY views_insert ON public.story_views FOR INSERT TO authenticated WITH CHECK(viewer_id=auth.uid() AND public.can_view_story(story_id));
CREATE TABLE public.point_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, reason text NOT NULL, points integer NOT NULL, source_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,source_key));
GRANT SELECT ON public.point_events TO authenticated; GRANT ALL ON public.point_events TO service_role;
ALTER TABLE public.point_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY points_read ON public.point_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.award_social_points() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='friendships' AND NEW.status='accepted' AND OLD.status='pending' THEN INSERT INTO public.point_events(user_id,reason,points,source_key) VALUES(NEW.requester_id,'New friend',10,'friend:'||NEW.recipient_id),(NEW.recipient_id,'New friend',10,'friend:'||NEW.requester_id) ON CONFLICT DO NOTHING; ELSIF TG_TABLE_NAME='stories' THEN INSERT INTO public.point_events(user_id,reason,points,source_key) VALUES(NEW.owner_id,'Daily story',5,'story:'||to_char(now() AT TIME ZONE 'UTC','YYYY-MM-DD')) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER friend_points AFTER UPDATE ON public.friendships FOR EACH ROW EXECUTE FUNCTION public.award_social_points();
CREATE TRIGGER story_points AFTER INSERT ON public.stories FOR EACH ROW EXECUTE FUNCTION public.award_social_points();
CREATE FUNCTION public.shared_gallery_access(path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.stories s WHERE s.storage_path=path AND public.can_view_story(s.id)) OR EXISTS(SELECT 1 FROM public.messages m WHERE m.storage_path=path AND auth.uid() IN (m.sender_id,m.recipient_id)); $$;
REVOKE ALL ON FUNCTION public.shared_gallery_access(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.shared_gallery_access(text) TO authenticated;
CREATE POLICY shared_gallery_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='gallery' AND public.shared_gallery_access(name));
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages,public.friendships,public.stories;
